----- src/app/ajs/components/camp-header.js -----
// The header of every page with the links between the areas.
angular.module("castra")
    .component("campHeader", {
        templateUrl: "app/ajs/components/camp-header.html",
        controller : Controller,
        bindings   : { title: "@", active: "<" }
    });

Controller.$inject = [ "$state" ];

function Controller ($state) {
    var $ctrl = this;

    $ctrl.isActive = function (name) {
        return $state.includes(name);
    };
}
----- src/app/ajs/components/pager-control.js -----
// Previous and next page buttons.
angular.module("castra.core")
    .component("pagerControl", {
        templateUrl: "app/ajs/components/pager-control.html",
        bindings   : { page: "<", pages: "<", onChange: "&" }
    });
----- src/app/ajs/components/section-title.js -----
// A section heading.
angular.module("castra.core")
    .component("sectionTitle", {
        template: "<h2 class=\"section-title section-title--{{ $ctrl.type || 'primary' }}\" id=\"{{ ::$ctrl.name }}\">{{ $ctrl.label }}</h2>",
        bindings: { label: "@", type: "@?", name: "@?" }
    });
----- src/app/ajs/features/armory/armory-page.js -----
// The armory page: helmets, shields and swords in stock.
angular.module("castra.core")
    .component("armoryPage", {
        templateUrl: "app/ajs/features/armory/armory-page.html",
        controller : Controller
    });

Controller.$inject = [ "armoryService", "$state" ];

function Controller (armoryService, $state) {
    var $ctrl = this;

    $ctrl.$onInit = function () {
        $ctrl.counting = false;
        armoryService.inventory().then(function (items) {
            $ctrl.items = items;
            $ctrl.shields = items.shields;
            $ctrl.gladii = items.gladii;
        });
    };

    $ctrl.recount = function () {
        $ctrl.counting = true;
        armoryService.inventory().then(function () {
            $state.reload();
        });
    };
}
----- src/app/ajs/features/armory/armory.routing.js -----
// ui-router states of the armory area.
angular.module("castra")
    .config(config);

config.$inject = [ "$stateProvider" ];

function config ($stateProvider) {
    $stateProvider
        .state("armory", {
            url: "/armory",
            component: "armoryPage"
        })
        .state("armory.helmets", {
            url: "/helmets",
            templateUrl: "app/ajs/features/armory/helmets-page.html",
            controller: HelmetsPageController,
            controllerAs: "$ctrl"
        })
        .state("armory.shields", {
            url: "/shields",
            component: "shieldList",
            resolve: {
                shields: [ "armoryService", function (armoryService) {
                    return armoryService.shields();
                } ]
            }
        });
}

HelmetsPageController.$inject = [ "armoryService" ];

function HelmetsPageController (armoryService) {
    var $ctrl = this;

    $ctrl.helmets = armoryService.cachedHelmets();
    $ctrl.spare = 0;
    $ctrl.size = "";
    $ctrl.sizes = [ { id: "s", label: "Small" }, { id: "m", label: "Medium" }, { id: "l", label: "Large" } ];
}
----- src/app/ajs/features/legions/legion-dashboard.js -----
// The legions page: every legion in camp with its cohorts.
angular.module("castra.core")
    .component("legionDashboard", {
        templateUrl: "app/ajs/features/legions/legion-dashboard.html",
        controller: LegionDashboardController
    });

LegionDashboardController.$inject = [ "legionService", "cohortStore", "$state" ];

function LegionDashboardController (legionService, cohortStore, $state) {
    var $ctrl = this;

    $ctrl.$onInit = function () {
        $ctrl.loading = true;
        legionService.list().then(function (legions) {
            $ctrl.legions = legions;
            $ctrl.firstLegion = legions[0];
            $ctrl.loading = false;
        });
        $ctrl.cohorts = cohortStore.all();
    };

    $ctrl.open = function (legion) {
        $state.go("legions.detail", { legionId: legion.id });
    };
}
----- src/app/ajs/features/legions/legions.routing.js -----
// ui-router states of the legions area.
angular.module("castra")
    .config(config);

config.$inject = [ "$stateProvider" ];

function config ($stateProvider) {
    $stateProvider
        .state("legions", {
            abstract: true,
            url: "/legions",
            template: "<ui-view></ui-view>"
        })
        .state("legions.list", {
            url: "",
            component: "legionDashboard"
        })
        .state("legions.detail", {
            url: "/:legionId",
            templateUrl: "app/ajs/features/legions/legion-detail.html",
            controller: LegionDetailController,
            controllerAs: "$ctrl",
            resolve: {
                legion: [ "$stateParams", "legionService", function ($stateParams, legionService) {
                    return legionService.find($stateParams.legionId);
                } ]
            }
        })
        .state("legions.standards", {
            url: "/standards",
            template: "<standard-bearer-list legions=\"$resolve.legions\"></standard-bearer-list>",
            resolve: {
                legions: [ "legionService", function (legionService) {
                    return legionService.list();
                } ]
            }
        });
}

LegionDetailController.$inject = [ "legion", "legionService", "$state" ];

function LegionDetailController (legion, legionService, $state) {
    var $ctrl = this;

    $ctrl.legion = legion;
    $ctrl.neighbours = [];
    $ctrl.today = Date.now();

    legionService.list().then(function (legions) {
        $ctrl.neighbours = legions.filter(function (other) {
            return other.id !== legion.id;
        });
    });

    $ctrl.pick = function (picked) {
        $state.go("legions.detail", { legionId: picked.id });
    };

    $ctrl.refresh = function () {
        $state.reload();
    };
}
----- src/app/ajs/features/patrols/patrol-board.js -----
// The patrols page: the log, the watches and the tents.
angular.module("castra.core")
    .component("patrolBoard", {
        templateUrl: "app/ajs/features/patrols/patrol-board.html",
        controller : Controller
    });

Controller.$inject = [ "patrolService", "reportCache", "$state" ];

function Controller (patrolService, reportCache, $state) {
    var $ctrl = this;

    $ctrl.$onInit = function () {
        $ctrl.query = "";
        $ctrl.nightOnly = false;
        patrolService.entries().then(function (entries) {
            $ctrl.entries = entries;
        });
        $ctrl.watches = patrolService.watches();
        $ctrl.tents = reportCache.get("tents") || [];
    };

    $ctrl.pickTent = function (tent) {
        $state.go("patrols.map", { tentId: tent.id });
    };
}
----- src/app/ajs/features/patrols/patrols.routing.js -----
// ui-router states of the patrols area.
angular.module("castra")
    .config(config);

config.$inject = [ "$stateProvider" ];

function config ($stateProvider) {
    $stateProvider
        .state("patrols", {
            url: "/patrols",
            component: "patrolBoard"
        })
        .state("patrols.reports", {
            url: "/reports",
            templateUrl: "app/ajs/features/patrols/reports-page.html",
            controller: ReportsPageController,
            controllerAs: "$ctrl"
        })
        .state("patrols.map", {
            url: "/map?tentId",
            template: "<tent-map tents=\"$resolve.tents\"></tent-map>",
            resolve: {
                tents: [ "patrolService", function (patrolService) {
                    return patrolService.tents();
                } ]
            }
        });
}

ReportsPageController.$inject = [ "reportCache", "patrolService" ];

function ReportsPageController (reportCache, patrolService) {
    var $ctrl = this;

    $ctrl.reports = reportCache.get("reports") || [];
    $ctrl.latest = patrolService.cachedEntries()[0];
    $ctrl.today = Date.now();
}
----- src/app/ajs/features/rations/ration-board.js -----
// The rations page: today's rations next to the state of the stores.
angular.module("castra.core")
    .component("rationBoard", {
        templateUrl: "app/ajs/features/rations/ration-board.html",
        controller : Controller
    });

Controller.$inject = [ "rationService", "supplyLedger", "$state" ];

function Controller (rationService, supplyLedger, $state) {
    var $ctrl = this;

    $ctrl.$onInit = function () {
        rationService.list().then(function (rations) {
            $ctrl.rations = rations;
        });
        $ctrl.ledger = supplyLedger.current();
        $ctrl.store = rationService.grainStore();
    };

    $ctrl.select = function (ration) {
        $state.go("rations.ledger", { rationId: ration.id });
    };
}
----- src/app/ajs/features/rations/rations.routing.js -----
// ui-router states of the rations area.
angular.module("castra")
    .config(config);

config.$inject = [ "$stateProvider" ];

function config ($stateProvider) {
    $stateProvider
        .state("rations", {
            url: "/rations",
            component: "rationBoard"
        })
        .state("rations.ledger", {
            url: "/ledger/:rationId",
            templateUrl: "app/ajs/features/rations/ration-ledger-page.html",
            controller: RationLedgerController,
            controllerAs: "$ctrl"
        })
        .state("rations.supply", {
            url: "/supply",
            template: "<supply-overview></supply-overview>"
        })
        .state("treasury", {
            url: "/treasury",
            template: "<treasury-page></treasury-page>"
        });
}

RationLedgerController.$inject = [ "rationService", "$stateParams" ];

function RationLedgerController (rationService, $stateParams) {
    var $ctrl = this;

    $ctrl.entry = { title: "", amount: 0, rationId: $stateParams.rationId };
    $ctrl.saving = false;
    $ctrl.notes = [];

    rationService.list().then(function (rations) {
        $ctrl.rations = rations;
    });

    $ctrl.touch = function () {
        $ctrl.dirty = true;
    };

    $ctrl.save = function () {
        $ctrl.saving = true;
        rationService.save($ctrl.entry).finally(function () {
            $ctrl.saving = false;
        });
    };
}
