// The cohorts of a legion, one page at a time.
angular.module("castra.core")
    .component("cohortTable", {
        templateUrl: "app/ajs/features/legions/components/cohort-table.html",
        controller : Controller,
        bindings   : { cohorts: "<", pageSize: "<" }
    });

function Controller () {
    var $ctrl = this;

    $ctrl.$onInit = function () {
        $ctrl.page = 1;
        $ctrl.pages = Math.ceil($ctrl.cohorts.length / $ctrl.pageSize);
        $ctrl.cohortSize = 480;
    };

    $ctrl.go = function (page) {
        $ctrl.page = page;
    };
}
