// One ration: what it is, how much of it and what it costs.
angular.module("castra.core")
    .component("rationRow", {
        templateUrl: "app/ajs/features/rations/components/ration-row.html",
        controller: RationRowController,
        bindings: { ration: "<", onSelect: "&", label: "@?" }
    });

RationRowController.$inject = [ "rationService", "$state" ];

function RationRowController (rationService, $state) {
    var $ctrl = this;

    $ctrl.update = function (value) {
        rationService.setAmount($ctrl.ration.id, value);
    };

    $ctrl.remove = function () {
        rationService.remove($ctrl.ration.id).then(function () {
            $state.reload();
        });
    };
}
----- src/app/ajs/features/rations/components/ration-summary.js -----
// One line that sums the rations up.
angular.module("castra.core")
    .component("rationSummary", {
        template: "<p class=\"ration-summary\">{{ $ctrl.rations.length }} rations, {{ $ctrl.weight() | rationUnit:'modius' }} in store</p>",
        controller: RationSummaryController,
        bindings: { rations: "<" }
    });

function RationSummaryController () {
    var $ctrl = this;

    $ctrl.weight = function () {
        return $ctrl.rations.reduce(function (sum, ration) {
            return sum + ration.weight;
        }, 0);
    };
}
----- src/app/ajs/features/rations/components/ration-table.js -----
// Rations as rows, with a total underneath.
angular.module("castra.core")
    .component("rationTable", {
        templateUrl: "app/ajs/features/rations/components/ration-table.html",
        controller : Controller,
        bindings   : { rations: "<", onSelect: "&" }
    });

function Controller () {
    var $ctrl = this;

    $ctrl.$onInit = function () {
        $ctrl.page = 1;
        $ctrl.pages = Math.ceil($ctrl.rations.length / 20);
        $ctrl.query = "";
        $ctrl.total = $ctrl.rations.reduce(function (sum, ration) {
            return sum + ration.cost;
        }, 0);
    };

    $ctrl.go = function (page) {
        $ctrl.page = page;
    };
}
