// Grain, wine and crates at a glance.
angular.module("castra.core")
    .component("supplyOverview", {
        templateUrl: "app/ajs/features/rations/components/supply-overview.html",
        controller : Controller
    });

Controller.$inject = [ "rationService", "supplyService", "notificationHub" ];

function Controller (rationService, supplyService, notificationHub) {
    var $ctrl = this;

    $ctrl.$onInit = function () {
        $ctrl.grainLevel = supplyService.level("grain");
        $ctrl.wineLevel = supplyService.level("wine");
        $ctrl.notes = [];
        $ctrl.crates = [];
        rationService.list().then(function (rations) {
            $ctrl.rations = rations;
        });
        notificationHub.info("Supply overview opened");
    };
}
